using UnityEngine;

[RequireComponent(typeof(Collider2D))]
public class MeleeAttack : MonoBehaviour, IAttackBehavior
{
    [Header("近战攻击")]
    public float damage = 10f;
    public float attackCooldown = 1.0f;

    private float _lastAttackTime = -10f;

    public bool TryAttack(Transform target)
    {
        if (Time.time < _lastAttackTime + attackCooldown) return false;
        if (target == null) return false;

        var dmg = target.GetComponent<IDamageable>();
        if (dmg != null)
        {
            dmg.TakeDamage(damage);
            _lastAttackTime = Time.time;
            return true;
        }

        return false;
    }

    private void OnTriggerStay2D(Collider2D other)
    {
        if (!other.CompareTag("Player")) return;
        if (Time.time < _lastAttackTime + attackCooldown) return;

        var damageable = other.GetComponent<IDamageable>();
        if (damageable != null)
        {
            damageable.TakeDamage(damage);
            _lastAttackTime = Time.time;
        }
    }
}

using UnityEngine;

/// <summary>
/// 远程攻击行为：定时朝玩家发射投射物。
/// 投射物预制体需挂有 Projectile 组件，RangedAttack 通过 Initialize() 配置其飞行参数。
/// </summary>
public class RangedAttack : MonoBehaviour, IAttackBehavior
{
    [Header("远程攻击")]
    public float damage = 8f;
    [Tooltip("两次攻击间隔（秒）")]
    public float attackCooldown = 1.5f;
    [Tooltip("投射物预制体（需挂有 Projectile 组件）")]
    public GameObject projectilePrefab;
    public float projectileSpeed = 6f;
    [Tooltip("投射物生成偏移（相对敌人位置）")]
    public Vector2 spawnOffset = Vector2.up * 0.5f;
    public float projectileLifetime = 3f;

    private float _lastAttackTime = -10f;

    public bool TryAttack(Transform target)
    {
        if (Time.time < _lastAttackTime + attackCooldown) return false;
        if (target == null) return false;
        if (projectilePrefab == null) return false;

        Vector2 dir = (target.position - transform.position).normalized;
        Vector2 spawnPos = (Vector2)transform.position + spawnOffset;

        GameObject obj = Instantiate(projectilePrefab, spawnPos, Quaternion.identity);
        Projectile proj = obj.GetComponent<Projectile>();
        if (proj != null)
        {
            proj.Initialize(dir, projectileSpeed, damage, Projectile.OwnerType.Enemy);
        }
        else
        {
            // 回退：无 Projectile 组件则手动销毁
            Destroy(obj, projectileLifetime);
        }

        _lastAttackTime = Time.time;
        return true;
    }
}

using UnityEngine;

/// <summary>
/// 攻击状态：停止移动，尝试用 IAttackBehavior 和技能攻击玩家。
/// 玩家离开攻击范围 → Chase。
/// </summary>
public class AttackState : EnemyStateBase
{
    public AttackState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        Core.Movement?.Stop();
    }

    public override void Tick()
    {
        if (Core.PlayerTarget == null || Core.config == null)
        {
            Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        Vector2 playerPos = Core.PlayerTarget.position;
        float sqrDist = ((Vector2)Core.transform.position - playerPos).sqrMagnitude;
        float attackSqr = Core.config.attackRange * Core.config.attackRange;

        // 玩家离开攻击范围 → 继续追击
        if (sqrDist > attackSqr * 1.2f)
        {
            Core.StateMachine.ChangeState(new ChaseState(Core));
            return;
        }

        // 尝试使用攻击行为
        Core.AttackBehavior?.TryAttack(Core.PlayerTarget);

        // 尝试释放技能
        if (Core.SkillManager != null && Core.SkillManager.SkillInstances.Count > 0)
        {
            Core.SkillManager.TryCastSkill(0, Core, Core.GetTargetDirection());
        }
    }
}

using UnityEngine;

/// <summary>
/// 追击状态：加速追向玩家。进入攻击范围 → Attack；丢失视线 → Search；脱离探测范围 → Patrol/Idle。
/// </summary>
public class ChaseState : EnemyStateBase
{
    public ChaseState(EnemyCore core) : base(core) { }

    public override void Tick()
    {
        if (Core.PlayerTarget == null || Core.config == null)
        {
            Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        Vector2 playerPos = Core.PlayerTarget.position;
        float sqrDist = ((Vector2)Core.transform.position - playerPos).sqrMagnitude;
        float detectionSqr = Core.config.detectionRange * Core.config.detectionRange;
        float attackSqr = Core.config.attackRange * Core.config.attackRange;

        // 超出探测范围 → 返回巡逻/空闲
        if (sqrDist > detectionSqr)
        {
            Core.Movement?.Stop();
            if (Core.config.patrolPoints != null && Core.config.patrolPoints.Count > 0)
                Core.StateMachine.ChangeState(new PatrolState(Core));
            else
                Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        // 视线检测
        bool canSee = Core.Movement.HasLineOfSight(playerPos, Core.config.detectionRange);

        if (!canSee)
        {
            // 丢失视线 → 搜索
            Core.StateMachine.ChangeState(new SearchState(Core));
            return;
        }

        Core.LastKnownPlayerPosition = playerPos;

        // 进入攻击范围
        if (sqrDist <= attackSqr)
        {
            Core.StateMachine.ChangeState(new AttackState(Core));
            return;
        }

        // 追击移动（加速）
        if (Core.Movement != null)
        {
            Core.Movement.MoveSpeed = Core.config.chaseSpeed;
            Core.Movement.MoveTowardsPosition(playerPos);
        }
    }
}

using UnityEngine;

/// <summary>
/// 空闲状态：原地待命，定期检测玩家。发现玩家 → Chase；有巡逻点 → Patrol。
/// </summary>
public class IdleState : EnemyStateBase
{
    public IdleState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        Core.Movement?.Stop();
    }

    public override void Tick()
    {
        if (Core.PlayerTarget == null) return;
        if (Core.config == null) return;

        // 检测玩家
        Vector2 playerPos = Core.PlayerTarget.position;
        bool canSee = Core.Movement.HasLineOfSight(playerPos, Core.config.detectionRange);

        if (canSee)
        {
            Core.LastKnownPlayerPosition = playerPos;
            Core.StateMachine.ChangeState(new ChaseState(Core));
            return;
        }

        // 有巡逻点则转入巡逻
        if (Core.config.patrolPoints != null && Core.config.patrolPoints.Count > 0)
        {
            Core.StateMachine.ChangeState(new PatrolState(Core));
            return;
        }
    }
}

using UnityEngine;

/// <summary>
/// 巡逻状态：沿配置的 patrolPoints 逐个移动，到达后在每个点短暂停留。
/// 发现玩家 → Chase。
/// </summary>
public class PatrolState : EnemyStateBase
{
    private int _currentIndex;
    private float _waitTimer;
    private static readonly float WaitPerPoint = 0.8f;
    private static readonly float ArriveThreshold = 0.3f;

    public PatrolState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        _currentIndex = 0;
        _waitTimer = 0f;
    }

    public override void Tick()
    {
        if (Core.PlayerTarget != null && Core.config != null)
        {
            Vector2 playerPos = Core.PlayerTarget.position;
            if (Core.Movement.HasLineOfSight(playerPos, Core.config.detectionRange))
            {
                Core.LastKnownPlayerPosition = playerPos;
                Core.StateMachine.ChangeState(new ChaseState(Core));
                return;
            }
        }

        if (Core.config == null || Core.config.patrolPoints == null || Core.config.patrolPoints.Count == 0)
        {
            Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        Vector2 target = Core.config.patrolPoints[_currentIndex];
        float sqrDist = ((Vector2)Core.transform.position - target).sqrMagnitude;

        if (sqrDist < ArriveThreshold * ArriveThreshold)
        {
            // 到达，等待
            Core.Movement?.Stop();
            _waitTimer += Time.deltaTime;
            if (_waitTimer >= WaitPerPoint)
            {
                _waitTimer = 0f;
                _currentIndex = (_currentIndex + 1) % Core.config.patrolPoints.Count;
            }
        }
        else
        {
            _waitTimer = 0f;
            Core.Movement?.MoveTowardsPosition(target);
            // 巡逻用 patrolSpeed
            if (Core.Movement != null)
                Core.Movement.MoveSpeed = Core.config.patrolSpeed;
        }
    }
}

using UnityEngine;

/// <summary>
/// 搜索状态：移动到玩家最后已知位置，到达后等待 searchDuration 秒。
/// 重新发现玩家 → Chase；超时 → Patrol/Idle。
/// </summary>
public class SearchState : EnemyStateBase
{
    private float _enterTime;
    private float _searchDuration = 2.5f;
    private bool _arrived;
    private static readonly float ArriveThreshold = 0.4f;

    public SearchState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        _enterTime = Time.time;
        _arrived = false;
    }

    public override void Tick()
    {
        // 期间重新发现玩家 → 立即追击
        if (Core.PlayerTarget != null && Core.config != null)
        {
            Vector2 playerPos = Core.PlayerTarget.position;
            if (Core.Movement.HasLineOfSight(playerPos, Core.config.detectionRange))
            {
                Core.LastKnownPlayerPosition = playerPos;
                Core.StateMachine.ChangeState(new ChaseState(Core));
                return;
            }
        }

        Vector2 lastPos = Core.LastKnownPlayerPosition;
        float sqrDist = ((Vector2)Core.transform.position - lastPos).sqrMagnitude;

        if (!_arrived)
        {
            if (sqrDist < ArriveThreshold * ArriveThreshold)
            {
                _arrived = true;
                _enterTime = Time.time; // 重置计时，开始等待
                Core.Movement?.Stop();
            }
            else
            {
                Core.Movement?.MoveTowardsPosition(lastPos, 0.8f);
            }
        }
        else
        {
            Core.Movement?.Stop();
            if (Time.time - _enterTime > _searchDuration)
            {
                // 超时，返回巡逻或空闲
                if (Core.config != null && Core.config.patrolPoints != null && Core.config.patrolPoints.Count > 0)
                    Core.StateMachine.ChangeState(new PatrolState(Core));
                else
                    Core.StateMachine.ChangeState(new IdleState(Core));
            }
        }
    }
}

using UnityEngine;

/// <summary>
/// 死亡状态：停止移动、禁用碰撞，延迟销毁 GameObject。
/// </summary>
public class DeadState : EnemyStateBase
{
    private float _destroyDelay = 0.5f;
    private float _deadTime;

    public DeadState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        _deadTime = Time.time;

        Core.Movement?.Stop();

        // 禁用所有 Collider2D 防止死亡后继续触发碰撞
        foreach (var col in Core.GetComponentsInChildren<Collider2D>())
        {
            col.enabled = false;
        }
    }

    public override void Tick()
    {
        if (Time.time - _deadTime >= _destroyDelay)
        {
            Object.Destroy(Core.gameObject);
        }
    }
}

