/// </summary>
public class IdleState : EnemyStateBase
{
    public IdleState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        Core.Movement?.Stop();
    }

    public override void Tick()
    {
        if (Core.PlayerTarget == null) return;
        if (Core.config == null) return;

        // 检测玩家
        Vector2 playerPos = Core.PlayerTarget.position;
        bool canSee = Core.Movement.HasLineOfSight(playerPos, Core.config.detectionRange);

        if (canSee)
        {
            Core.LastKnownPlayerPosition = playerPos;
            Core.StateMachine.ChangeState(new ChaseState(Core));
            return;
        }

        // 有巡逻点则转入巡逻
        if (Core.config.patrolPoints != null && Core.config.patrolPoints.Count > 0)
        {
            Core.StateMachine.ChangeState(new PatrolState(Core));
            return;
        }
    }
}

using UnityEngine;

/// <summary>
/// 巡逻状态：沿配置的 patrolPoints 逐个移动，到达后在每个点短暂停留。
/// 发现玩家 → Chase。
/// </summary>
public class PatrolState : EnemyStateBase
{
    private int _currentIndex;
    private float _waitTimer;
    private static readonly float WaitPerPoint = 0.8f;
    private static readonly float ArriveThreshold = 0.3f;

    public PatrolState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        _currentIndex = 0;
        _waitTimer = 0f;
    }

    public override void Tick()
    {
        if (Core.PlayerTarget != null && Core.config != null)
        {
            Vector2 playerPos = Core.PlayerTarget.position;
            if (Core.Movement.HasLineOfSight(playerPos, Core.config.detectionRange))
            {
                Core.LastKnownPlayerPosition = playerPos;
                Core.StateMachine.ChangeState(new ChaseState(Core));
                return;
            }
        }

        if (Core.config == null || Core.config.patrolPoints == null || Core.config.patrolPoints.Count == 0)
        {
            Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        Vector2 target = Core.config.patrolPoints[_currentIndex];
        float sqrDist = ((Vector2)Core.transform.position - target).sqrMagnitude;

        if (sqrDist < ArriveThreshold * ArriveThreshold)
        {
            // 到达，等待
            Core.Movement?.Stop();
            _waitTimer += Time.deltaTime;
            if (_waitTimer >= WaitPerPoint)
            {
                _waitTimer = 0f;
                _currentIndex = (_currentIndex + 1) % Core.config.patrolPoints.Count;
            }
        }
        else
        {
            _waitTimer = 0f;
            Core.Movement?.MoveTowardsPosition(target);
            // 巡逻用 patrolSpeed
            if (Core.Movement != null)
                Core.Movement.MoveSpeed = Core.config.patrolSpeed;
        }
    }
}

using UnityEngine;

/// <summary>
/// 搜索状态：移动到玩家最后已知位置，到达后等待 searchDuration 秒。
/// 重新发现玩家 → Chase；超时 → Patrol/Idle。
/// </summary>
public class SearchState : EnemyStateBase
{
    private float _enterTime;
    private float _searchDuration = 2.5f;
    private bool _arrived;
    private static readonly float ArriveThreshold = 0.4f;

    public SearchState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        _enterTime = Time.time;
        _arrived = false;
    }

    public override void Tick()
    {
        // 期间重新发现玩家 → 立即追击
        if (Core.PlayerTarget != null && Core.config != null)
        {
            Vector2 playerPos = Core.PlayerTarget.position;
            if (Core.Movement.HasLineOfSight(playerPos, Core.config.detectionRange))
            {
                Core.LastKnownPlayerPosition = playerPos;
                Core.StateMachine.ChangeState(new ChaseState(Core));
                return;
            }
        }

        Vector2 lastPos = Core.LastKnownPlayerPosition;
        float sqrDist = ((Vector2)Core.transform.position - lastPos).sqrMagnitude;

        if (!_arrived)
        {
            if (sqrDist < ArriveThreshold * ArriveThreshold)
            {
                _arrived = true;
                _enterTime = Time.time; // 重置计时，开始等待
                Core.Movement?.Stop();
            }
            else
            {
                Core.Movement?.MoveTowardsPosition(lastPos, 0.8f);
            }
        }
        else
        {
            Core.Movement?.Stop();
            if (Time.time - _enterTime > _searchDuration)
            {
                // 超时，返回巡逻或空闲
                if (Core.config != null && Core.config.patrolPoints != null && Core.config.patrolPoints.Count > 0)
                    Core.StateMachine.ChangeState(new PatrolState(Core));
                else
                    Core.StateMachine.ChangeState(new IdleState(Core));
            }
        }
    }
}

